        path = []
        current = target
        while current != source:
            for neighbor in range(V):
                if dist[current][neighbor] == dist[current][target] - dist[target][neighbor]:
                    current = neighbor
                    path.append(current)
                    break
        path.append(source)
        return (dist[source][target], path[::-1])

